settings.custom_liquid:
{%- assign t = product.title | escape -%}
{%- assign name = t -%}
{%- assign tag = '' -%}
{%- if t contains '(' -%}
  {%- assign parts = t | split: '(' -%}
  {%- assign name = parts[0] | strip -%}
  {%- assign tag = parts[1] | remove: ')' | strip -%}
{%- endif -%}
<style>
.sc-title h1{font-size:2.2rem;line-height:1.15;margin:0 0 .4rem;letter-spacing:.02em;word-break:normal;overflow-wrap:anywhere}
.sc-title .sc-tagline{margin:0 0 1rem;font-size:1.25rem;letter-spacing:.14em;text-transform:uppercase;opacity:.75}
@media (min-width:750px){.sc-title h1{font-size:3rem}}
.product__info-container:has(.free-shipping-badge) .product__tax{display:none}
.sc-pitch{margin:1.2rem 0 1.6rem}
.sc-pitch p{margin:0}
.sc-sizelink{display:inline-block;margin:0 0 1.6rem;font-size:1.4rem;text-decoration:underline;text-underline-offset:.3rem;cursor:pointer}
#sc-details .accordion__content table{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse;font-size:1.15rem;margin:1rem 0 2rem}
#sc-details .accordion__content td,#sc-details .accordion__content th{padding:.6rem .35rem;border-bottom:1px solid rgba(var(--color-foreground),.2);white-space:normal;text-align:left}
#sc-details .accordion__content h3{font-size:1.6rem;margin:2rem 0 .8rem}
#sc-details .accordion__content ul{padding-left:2rem}
.sc-sticky-buy{display:none}
.sc-sticky-buy.is-visible{display:block;position:fixed;left:0;right:0;bottom:0;z-index:50;padding:1rem 1.6rem calc(1rem + env(safe-area-inset-bottom));background:#fff;box-shadow:0 -2px 12px rgba(0,0,0,.25)}
.sc-sticky-buy .button{max-width:48rem;margin:0 auto;display:flex;width:100%}
@media (max-width:749px){.sc-sticky-buy.is-visible{padding-right:7rem}}
.sc-trust{list-style:none;margin:1.2rem 0 0;padding:1.2rem 0 0;border-top:1px solid rgba(var(--color-foreground),.12);font-size:1.3rem;line-height:1.5}.sc-trust li{position:relative;padding-left:2.2rem;margin:0 0 .5rem}.sc-trust li:before{content:'\2713';position:absolute;left:0;top:0;font-weight:700;color:#1a7d33}.sc-specs ul{margin:0 0 1.2rem;padding-left:1.8rem;font-size:1.4rem;line-height:1.55}.sc-meet{margin:.4rem 0 1.6rem;font-size:1.4rem;font-weight:700}.sc-meet a{text-decoration:underline;text-underline-offset:.3rem}
</style>
<div class="product__title sc-title">
  <h1>{{ name }}</h1>
  {%- if tag != '' -%}<p class="sc-tagline">{{ tag }}</p>{%- endif -%}
</div>

{%- if product.description contains 'Size guide' or product.description contains 'size guide' or product.description contains 'Size Guide' -%}
<a class="sc-sizelink" href="#sc-details">Size guide</a>
<script>
(function () {
  var link = document.querySelector('.sc-sizelink');
  if (!link) { return; }
  link.addEventListener('click', function (e) {
    e.preventDefault();
    var d = document.querySelector('.product__accordion details');
    if (!d) { return; }
    d.open = true;
    var target = null;
    d.querySelectorAll('strong,h2,h3,h4,p').forEach(function (s) { if (!target && s.textContent.trim().length < 40 && /size guide/i.test(s.textContent)) { target = s; } });
    (target || d).scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
})();
</script>
{%- endif -%}

{%- if product.description != blank -%}
{%- assign d = product.description -%}
{%- assign specs = '' -%}
{%- if d contains '<ul' -%}
  {%- assign parts = d | split: '<ul' -%}
  {%- assign ul = parts[1] | split: '</ul>' | first -%}
  {%- assign specs = '<ul' | append: ul | append: '</ul>' -%}
{%- endif -%}
{%- assign paras = d | split: '</p>' -%}
{%- assign hook = '' -%}
{%- assign story = '' -%}
{%- for p in paras -%}
  {%- if p contains '<li' or p contains 'PRODUCT TITLE' -%}{%- continue -%}{%- endif -%}
  {%- assign txt = p | strip_html | strip -%}
  {%- if txt == '' -%}{%- continue -%}{%- endif -%}
  {%- if hook == '' and story == '' and txt.size <= 70 -%}{%- assign hook = txt -%}{%- continue -%}{%- endif -%}
  {%- if story == '' and txt.size > 60 -%}{%- assign story = txt -%}{%- break -%}{%- endif -%}
{%- endfor -%}
<div class="sc-pitch rte">
  {%- if specs != '' -%}<div class="sc-specs">{{ specs }}</div>{%- endif -%}
  {%- if hook != '' -%}<p><strong>{{ hook }}</strong></p>{%- endif -%}
  {%- if story != '' -%}<p>{{ story }}</p>{%- endif -%}
</div>
{%- endif -%}

{%- if product.type == 'Digital Download' -%}
<ul class="sc-trust">
  <li>Download link emailed the moment you pay. Nothing is posted.</li>
  <li>Print it at home or at any print shop. Personal use licence.</li>
</ul>
{%- else -%}
<ul class="sc-trust">
  <li>Made to order: printed in 2–5 business days, then 3–7 business days in transit.</li>
  <li>Tracking link emailed the moment it ships.</li>
  {%- unless product.handle == 'nft-shirt' or product.handle == 'nft-poster' -%}
  <li>30-day returns. Damaged or wrong item? We make it right.</li>
  {%- endunless -%}
</ul>
{%- endif -%}

{%- assign ch = '' -%}{%- assign cn = '' -%}
{%- assign hay = product.tags | join: '|' | append: '|' | append: product.title | downcase -%}
{%- if hay contains 'major wood' -%}{%- assign ch = 'major-wood' -%}{%- assign cn = 'Major Wood' -%}
{%- elsif hay contains 'rear admiral' -%}{%- assign ch = 'the-rear-admiral' -%}{%- assign cn = 'The Rear Admiral' -%}
{%- elsif hay contains 'hanky' -%}{%- assign ch = 'hammerin-hanky' -%}{%- assign cn = "Hammerin' Hanky" -%}
{%- elsif hay contains 'slick willy' -%}{%- assign ch = 'slick-willy' -%}{%- assign cn = 'Slick Willy' -%}
{%- elsif hay contains 'velvet python' -%}{%- assign ch = 'the-velvet-python' -%}{%- assign cn = 'The Velvet Python' -%}
{%- elsif hay contains 'the grip' -%}{%- assign ch = 'the-grip' -%}{%- assign cn = 'The Grip' -%}
{%- endif -%}
{%- if ch != '' -%}<p class="sc-meet"><a href="/pages/{{ ch }}">Meet {{ cn }} →</a></p>{%- endif -%}

{%- comment -%} Pair it with an NFT (25 Oct 2026). Only on the NFT Shirt and NFT Poster pages, and only once the Build your bundle page is published. {%- endcomment -%}
{%- if product.handle == 'nft-shirt' or product.handle == 'nft-poster' -%}
{%- assign bp = pages['build-your-bundle'] -%}
{%- if bp != blank and bp.handle == 'build-your-bundle' -%}
{%- if product.handle == 'nft-shirt' -%}{%- assign pq = 'shirt' -%}{%- else -%}{%- assign pq = 'poster' -%}{%- endif -%}
<style>.product__tax{display:none!important}.product-form__buttons,.product-form__quantity,quantity-input,.sc-sticky,.sc-sticky-buy,.product__sticky-bar{display:none!important}.sc-pair{background:rgba(var(--color-foreground),.05);border-left:4px solid rgb(var(--color-foreground));padding:16px 18px;margin:0 0 20px;font-size:1.4rem;line-height:1.6}.sc-pair p{margin:0 0 12px}.sc-pair .button{width:100%}</style>
<div class="sc-pair">
  <p><strong>This print is made for one digital artwork.</strong><br>Pick the artwork and the print together. The print price drops with the artwork's grade.</p>
  <a class="button button--secondary" href="{{ bp.url }}?print={{ pq }}">Pair it with an NFT</a>
</div>
{%- endif -%}
{%- endif -%}
